import { Effect, Schema, SchemaGetter, SchemaIssue } from "effect";
import * as z from "zod";

export interface FromZodAnnotations {
  readonly identifier: string;
  readonly description?: string | undefined;
}

/**
 * Bridges a zod schema into Effect Schema, for wire formats shared through
 * `@sigle/sdk` where zod is the single source of truth.
 *
 * Decoding delegates to zod and returns its parsed output. The JSON codec is
 * linked to `Schema.Json` carrying the JSON Schema generated by zod, so the
 * OpenAPI specification documents the real shape instead of an opaque value.
 */
export const fromZod = <T>(
  zodSchema: z.ZodType<T>,
  annotations: FromZodAnnotations,
) => {
  const { $schema: _, ...jsonSchema } = z.toJSONSchema(zodSchema, {
    target: "draft-2020-12",
    io: "input",
  });

  const Encoded = Schema.Json.check(
    Schema.makeFilter(() => true, {
      ...annotations,
      toJsonSchema: () => jsonSchema,
    }),
  );

  return Schema.declareConstructor<T>()(
    [],
    () => (input, _self, options) => {
      const parsed = zodSchema.safeParse(input);

      return parsed.success
        ? Effect.succeed(parsed.data)
        : Effect.fail(
            new SchemaIssue.InvalidValue(
              { message: z.prettifyError(parsed.error) },
              input,
              options,
            ),
          );
    },
    {
      ...annotations,
      toCodecJson: () =>
        Schema.link<T>()(Encoded, {
          decode: SchemaGetter.passthrough({ strict: false }),
          encode: SchemaGetter.passthrough({ strict: false }),
        }),
    },
  );
};
